def scope(path,tier):
    if path not in NOTES or tier not in range(1,7): raise ValueError('Not reviewed in FM-16AH')
    if tier==6 and path in ('conjugate-product','exact-radians','polar-quotients','standard-cartesian'): return 'enrichment_only'
    return {1:'prerequisite_bridge_reviewed',2:'conceptual_diagnostic_reviewed',3:'syllabus_linked_candidate',4:'syllabus_linked_candidate',5:'syllabus_linked_candidate',6:'challenge_candidate'}[tier]
